<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { namespaceContext, namespaceContextOptions, setNamespaceContext } from '../pkg/simple-network-manager/data/namespace-context';
const opened=ref(false),search=ref('');const root=ref<HTMLElement|null>(null);
const options=computed(()=>[{value:'all',label:'All Namespaces'},...namespaceContextOptions.value].filter(option=>option.label.toLowerCase().includes(search.value.toLowerCase())));
const label=computed(()=>!namespaceContext.value.length?'All Namespaces':namespaceContext.value.length===1?namespaceContextOptions.value.find(option=>option.value===namespaceContext.value[0])?.label||'Selected Namespace':`${namespaceContext.value.length} Namespaces Selected`);
const selected=(value:string)=>value==='all'?!namespaceContext.value.length:namespaceContext.value.includes(value);
function choose(value:string){if(value==='all')setNamespaceContext([]);else if(value.startsWith('all://')||value.startsWith('namespaced://'))setNamespaceContext([value]);else setNamespaceContext(selected(value)?namespaceContext.value.filter(item=>item!==value):[...namespaceContext.value.filter(item=>item.startsWith('ns://')||item.startsWith('project://')),value]);}
function outside(event:Event){if(!root.value?.contains(event.target as Node))opened.value=false;}
onMounted(()=>document.addEventListener('pointerdown',outside));onBeforeUnmount(()=>document.removeEventListener('pointerdown',outside));
</script>
<template><div ref="root" class="host-namespace" @keydown.esc.stop="opened=false"><button type="button" class="namespace-trigger" :aria-expanded="opened" aria-haspopup="listbox" aria-controls="global-namespace-options" aria-label="Global Namespace Selector" @click="opened=!opened">{{label}}<span aria-hidden="true">{{opened?'⌃':'⌄'}}</span></button><div v-if="opened" class="namespace-popup"><input v-model="search" type="search" aria-label="Search Global Namespaces" placeholder="Search Namespaces…"><div id="global-namespace-options" role="listbox" aria-label="Global Namespaces" aria-multiselectable="true"><button v-for="option in options" :key="option.value" type="button" role="option" :aria-selected="selected(option.value)" @click="choose(option.value)"><span>{{option.label}}</span><span v-if="selected(option.value)" aria-hidden="true">✓</span></button></div></div></div></template>
<style scoped>.host-namespace{position:relative;width:300px;font-size:14px}.namespace-trigger{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:40px;border:1px solid #91b8dc;background:#242b35;color:#dce3ed;padding:8px 14px;border-radius:4px;font:inherit}.namespace-popup{position:absolute;right:0;top:calc(100% - 1px);z-index:2000;width:360px;max-width:calc(100vw - 30px);background:#242b35;border:1px solid #91b8dc;border-radius:0 0 4px 4px;padding:8px}.namespace-popup input{width:100%;padding:9px;border:1px solid #91b8dc;border-radius:4px;background:#242b35;color:#dce3ed;font:inherit}.namespace-popup [role=listbox]{max-height:min(480px,60dvh);overflow:auto;margin-top:10px}.namespace-popup [role=option]{display:flex;align-items:center;justify-content:space-between;padding:9px;width:100%;border:0;background:transparent;color:#dce3ed;font:inherit;text-align:left}.namespace-popup [role=option][aria-selected=true]{color:#a9d2ff;background:#353d50}.namespace-popup [role=option]:hover{background:#353d50}button{cursor:pointer}button:focus-visible,input:focus-visible{outline:2px solid #73b5ff;outline-offset:2px}</style>
